// Specify the calendar address
const calendarId = "deya.humain@gmail.com";

// Get the array of busy times from the calendar output
const busyTimes = $input.first().json[calendarId]?.busy || [];

// Define the start time (24 hours from now)
let proposedStart = new Date(new Date().getTime() + (24 * 60 * 60 * 1000));

function isWeekend(date) {
    const day = date.getUTCDay();
    return day === 5 || day === 6; 
}

function adjustToWorkingHours(date) {
    let saTime = new Date(date.getTime() + (3 * 60 * 60 * 1000));

    let mins = saTime.getUTCMinutes();
    saTime.setUTCMinutes(mins >= 30 ? 30 : 0, 0, 0);

    if (saTime.getUTCHours() >= 16) {
        saTime.setUTCDate(saTime.getUTCDate() + 1);
        saTime.setUTCHours(9, 0, 0, 0);
    } else if (saTime.getUTCHours() < 9) {
        saTime.setUTCHours(9, 0, 0, 0);
    }

    while (isWeekend(saTime)) {
        saTime.setUTCDate(saTime.getUTCDate() + 1);
        saTime.setUTCHours(9, 0, 0, 0);
    }
    return new Date(saTime.getTime() - (3 * 60 * 60 * 1000));
}

// Apply the working hours logic to our initial start time
proposedStart = adjustToWorkingHours(proposedStart);
let proposedEnd = new Date(proposedStart.getTime() + (30 * 60 * 1000)); // 30 minutes interview

let slotFound = false;
let attempts = 0;

while (!slotFound && attempts < 100) {
    let isFree = true;

    for (const busy of busyTimes) {
        const busyStart = new Date(busy.start);
        const busyEnd = new Date(busy.end);

        // If there is an overlap with a busy event, it is not free
        if (proposedStart < busyEnd && proposedEnd > busyStart) {
            isFree = false;
            break;
        }
    }

    if (isFree) {
        slotFound = true;
        break;
    }

    // Move forward by 30 minutes
    proposedStart = new Date(proposedStart.getTime() + (30 * 60 * 1000));

    proposedStart = adjustToWorkingHours(proposedStart);
    proposedEnd = new Date(proposedStart.getTime() + (30 * 60 * 1000));

    attempts++;
}

if (!slotFound) {
    throw new Error("No free working slots available.");
}

return {
    interview_start: proposedStart.toISOString(),
    interview_end: proposedEnd.toISOString()
};

